INSERT INTO `gnb_perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`) VALUES ('C010020004', 'RLC.NbrPktDl', '小区下行RLC SDU发送包数', 'The number of SDU packets in the downstream RLC layer is accumulated. Each service type corresponds to a submeasurement item.', '在小区范围内，对下行RLC层SDU发送包数进行累加统计。每个业务类型对应一个子测量项。', '2d7a9006c2461f5d6a7dd503c9d2068d', NULL, '整数', 'number', 'admin', '2023-10-18 00:00:00', '1', '1', 'C010020004', 'sum', '');
INSERT INTO `gnb_perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`) VALUES ('C010020005', 'RLC.PktDelayDL', '小区RLC下行数据包平均处理时延', 'Within the cell range, statistics start from the first shard of the RLC layer of the base station until the MAC layer of the base station receives the HARQ ACK of the packet', '在小区范围内，统计从基站的RLC层收到上层数据包的第一个分片开始，直至基站的MAC层收到UE对该数据包的HARQ ACK。', '2d7a9006c2461f5d6a7dd503c9d2068d', NULL, '整数', 'ms', 'admin', '2023-10-18 00:00:00', '1', '1', 'C010020005', 'sum', '');
INSERT INTO `gnb_perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`) VALUES ('C010020006', 'RLC.UpLastTtiOctUl', '小区用户面RLC SDU上行尾包字节数', 'During the measurement period, the cumulative cache area cleared the number of RLC SDU bytes successfully received by the last TTI through the empty port.', '在测量周期内，累加缓存区清空前最后一个TTI通过空口成功接收的RLC SDU字节数。', '2d7a9006c2461f5d6a7dd503c9d2068d', NULL, '浮点数', 'KByte', 'admin', '2023-10-18 00:00:00', '1', '1', 'C010020006', 'sum', '');
INSERT INTO `gnb_perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`) VALUES ('C010020007', 'RLC.UpLastTtiOctDl', '小区用户面RLC SDU下行尾包字节数', 'During the measurement period, the cumulative cache area cleared the number of RLC SDU bytes successfully sent by the last TTI through the empty port.', '在测量周期内，累加缓存区清空前最后一个TTI通过空口成功发送的RLC SDU字节数。', '2d7a9006c2461f5d6a7dd503c9d2068d', NULL, '浮点数', 'KByte', 'admin', '2023-10-18 00:00:00', '1', '1', 'C010020007', 'sum', '');
INSERT INTO `gnb_perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`) VALUES ('C010020008', 'RLC.ThrpTimeUL', '小区RLC层接收上行数据的业务总时长', 'In the cell range, the uplink RLC cache that distinguishes the S-NSSAI statistics summing each UE per DRB is not empty total time (excluding the last TTI).', '在小区范围内，区分S-NSSAI统计累加每个UE每个DRB的激活DRB的上行RLC缓存不为空总时长（不含最后一个TTI）。', '2d7a9006c2461f5d6a7dd503c9d2068d', NULL, '整数', 'ms', 'admin', '2023-10-18 00:00:00', '1', '1', 'C010020008', 'sum', '');
INSERT INTO `gnb_perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`) VALUES ('C010020009', 'RLC.ThrpTimeDL', '小区RLC层接收下行数据的业务总时长', 'Within the cell range, the downlink RLC cache distinguishing S-NSSAI statistics summing each UE per DRB is not empty total time (excluding the last TTI).', '在小区范围内，区分S-NSSAI统计累加每个UE每个DRB的激活DRB的下行RLC缓存不为空总时长（不含最后一个TTI）。', '2d7a9006c2461f5d6a7dd503c9d2068d', NULL, '整数', 'ms', 'admin', '2023-10-18 00:00:00', '1', '1', 'C010020009', 'sum', '');
